using UnityEngine;
using Gsplat;
namespace MonetGarden {
[DefaultExecutionOrder(-50)] public class GardenGaussianTransition:MonoBehaviour {
 public GsplatRenderer rendererSource;[Range(.001f,.01f)]public float pointSize=.004f;[Range(.1f,4)]public float spread=1.35f;[Range(.01f,.5f)]public float assemblyDensity=.12f;
 public bool Running{get;private set;}GardenExperience flow;GsplatEffectType savedType;float savedSize,savedFloat,savedWave,savedAlpha,savedTwinkle,savedBrightness;bool saved;
 public void Initialize(GardenExperience experience){flow=experience;if(!rendererSource)rendererSource=FindObjectOfType<GsplatRenderer>();}
 public void Begin(){if(!rendererSource)return;savedType=rendererSource.effectType;savedSize=rendererSource.uniformPointSize;savedFloat=rendererSource.uniformFloatAmplitude;savedWave=rendererSource.uniformWaveAmplitude;savedAlpha=rendererSource.uniformPointAlpha;savedTwinkle=rendererSource.uniformTwinkleIntensity;savedBrightness=rendererSource.uniformPointBrightness;saved=true;Running=true;rendererSource.effectType=GsplatEffectType.UniformSpherePoints;rendererSource.uniformFloatAmplitude=0;rendererSource.uniformWaveAmplitude=0;rendererSource.uniformTwinkleIntensity=.03f;rendererSource.uniformPointSize=pointSize;rendererSource.uniformPointAlpha=1;rendererSource.uniformPointBrightness=1;Tick(0);}
 public void Tick(float progress){if(!Running||!rendererSource||!flow.SelectedArtwork)return;var cam=flow.player.viewCamera;float distance=2.4f;float viewHeight=2*distance*Mathf.Tan(cam.fieldOfView*Mathf.Deg2Rad*.5f);float aspect=(float)Screen.width/Mathf.Max(1,Screen.height);var tex=flow.SelectedArtwork.originalPainting;float imageAspect=(float)tex.width/tex.height;float imageWidth=Mathf.Min(viewHeight*aspect,viewHeight*imageAspect);float imageHeight=imageWidth/imageAspect;var source=rendererSource.transform;var xr=GardenXRBridge.Active;bool vr=xr&&xr.IsVR&&xr.presentation&&xr.presentation.PaintingAnchor;Vector3 center=vr?xr.presentation.PaintingAnchor.position:cam.transform.position+cam.transform.forward*distance;Vector3 right=vr?xr.presentation.PaintingRight:cam.transform.right*imageWidth;Vector3 up=vr?xr.presentation.PaintingUp:cam.transform.up*imageHeight;Shader.SetGlobalFloat("_MonetSplatActive",1);Shader.SetGlobalFloat("_MonetSplatProgress",progress);Shader.SetGlobalFloat("_MonetSplatSpread",spread);Shader.SetGlobalFloat("_MonetAssemblyDensity",assemblyDensity);Shader.SetGlobalVector("_MonetAssemblyCenter",source.InverseTransformPoint(center));Shader.SetGlobalVector("_MonetAssemblyRight",source.InverseTransformVector(right));Shader.SetGlobalVector("_MonetAssemblyUp",source.InverseTransformVector(up));Shader.SetGlobalTexture("_MonetAssemblyPainting",tex);}
 public void Restore(){Shader.SetGlobalFloat("_MonetSplatActive",0);Running=false;if(saved&&rendererSource){rendererSource.effectType=savedType;rendererSource.uniformPointSize=savedSize;rendererSource.uniformFloatAmplitude=savedFloat;rendererSource.uniformWaveAmplitude=savedWave;rendererSource.uniformPointAlpha=savedAlpha;rendererSource.uniformTwinkleIntensity=savedTwinkle;rendererSource.uniformPointBrightness=savedBrightness;saved=false;}}
 void OnDisable(){Restore();}
}}
